[Route("products")]
public class ProductsController : Controller
{
    // GET /products/electronics  — but also matches /products/5!
    [HttpGet("{category}")]
    public IActionResult ByCategory(string category) => View(model: category);

    // GET /products/5 — but also matches /products/electronics!
    [HttpGet("{id}")]
    public IActionResult Details(int id) => View(model: id);
}

[Route("products")]
public class ProductsController : Controller
{
    // Matches /products/5, /products/100 — but NOT /products/abc
    [HttpGet("{id:int:min(1)}")]
    public IActionResult Details(int id) => View(model: id);

    // Matches /products/page/1 through /products/page/50
    [HttpGet("page/{page:int:range(1,50)}")]
    public IActionResult List(int page) => View(model: page);

    // Matches GUID format IDs like /products/550e8400-e29b...
    [HttpGet("{id:guid}")]
    public IActionResult DetailsByGuid(Guid id) => View(model: id);
}

// id must be an integer between 1 and 1000
[HttpGet("{id:int:range(1,1000)}")]
public IActionResult Edit(int id) => View(model: id);

// Combined with a regex constraint on a string parameter
// slug must be non-empty and contain only lowercase letters and hyphens
[HttpGet("{slug:required:regex(^[a-z-]+$)}")]
public IActionResult Post(string slug) => View(model: slug);

// Matches slugs like: my-first-post, aspnet-core-guide, hello-world
[HttpGet("{slug:regex(^[a-z0-9]+(?:-[a-z0-9]+)*$)}")]
public IActionResult Post(string slug) => View(model: slug);

// /blog/hello-world      -> matches
// /blog/Hello-World      -> does NOT match (uppercase not allowed)
// /blog/hello_world      -> does NOT match (underscore not allowed)
